// ============================================================================
// MIPI_SoundWire_apb: APB4 register wrapper around MIPI_SoundWire_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/MIPI_SoundWire.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/MIPI_SoundWire.md
// ============================================================================
module MIPI_SoundWire_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sw_clk_o,
  output logic sw_clk_oe,
  input logic sw_clk_i,
  output logic sw_dat_o,
  output logic sw_dat_oe,
  input logic sw_dat_i,
  output logic reg_we,
  output logic reg_re,
  output logic [15:0] reg_addr,
  output logic [7:0] reg_wdata,
  input logic [7:0] reg_rdata
);
  localparam logic [31:0] ID_VALUE = 32'h534E0200;

  // ---------------- core ----------------
  logic          c_cfg_manager;
  logic [4:0]    c_cfg_div;
  logic [1:0]    c_cfg_cols;
  logic [3:0]    c_cfg_dev;
  logic [3:0]    c_cfg_tx_col;
  logic [3:0]    c_cfg_rx_col;
  logic          c_cmd_valid;
  logic          c_cmd_ready;
  logic [1:0]    c_cmd_op;
  logic [3:0]    c_cmd_dev;
  logic [15:0]   c_cmd_addr;
  logic [7:0]    c_cmd_wdata;
  logic          c_rsp_valid;
  logic          c_rsp_ack;
  logic          c_rsp_nak;
  logic [7:0]    c_rsp_rdata;
  logic [15:0]   c_ping_status;
  logic [1:0]    c_dev_status;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [31:0]   c_tx_data;
  logic          c_tx_underrun;
  logic          c_rx_valid;
  logic [31:0]   c_rx_data;
  logic          c_locked;
  logic          c_lost_sync;
  logic          c_par_err;
  MIPI_SoundWire_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_manager(c_cfg_manager),
    .cfg_div(c_cfg_div),
    .cfg_cols(c_cfg_cols),
    .cfg_dev(c_cfg_dev),
    .cfg_tx_col(c_cfg_tx_col),
    .cfg_rx_col(c_cfg_rx_col),
    .sw_clk_o(sw_clk_o),
    .sw_clk_oe(sw_clk_oe),
    .sw_clk_i(sw_clk_i),
    .sw_dat_o(sw_dat_o),
    .sw_dat_oe(sw_dat_oe),
    .sw_dat_i(sw_dat_i),
    .cmd_valid(c_cmd_valid),
    .cmd_ready(c_cmd_ready),
    .cmd_op(c_cmd_op),
    .cmd_dev(c_cmd_dev),
    .cmd_addr(c_cmd_addr),
    .cmd_wdata(c_cmd_wdata),
    .rsp_valid(c_rsp_valid),
    .rsp_ack(c_rsp_ack),
    .rsp_nak(c_rsp_nak),
    .rsp_rdata(c_rsp_rdata),
    .ping_status(c_ping_status),
    .dev_status(c_dev_status),
    .reg_we(reg_we),
    .reg_re(reg_re),
    .reg_addr(reg_addr),
    .reg_wdata(reg_wdata),
    .reg_rdata(reg_rdata),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_underrun(c_tx_underrun),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .locked(c_locked),
    .lost_sync(c_lost_sync),
    .par_err(c_par_err)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [10:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [21:0] r_CFG;   // 12'h014 CFG
  logic [29:0] h_CMD;   // 12'h018 CMD holding register
  logic [9:0] h_RSP;   // 12'h01C RSP holding register
  logic [31:0] h_TX;   // 12'h020 TX holding register
  logic [31:0] h_RX;   // 12'h024 RX holding register
  logic full_CMD;
  logic avail_RSP;
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 22'h116;
      h_CMD <= '0;
      h_RSP <= '0;
      h_TX <= '0;
      h_RX <= '0;
      full_CMD <= 1'b0;
      avail_RSP <= 1'b0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[10:0] & wmask[10:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[21:0]) | (PWDATA[21:0] & wmask[21:0]);
      if (wr && hit[6] && !full_CMD) h_CMD <= (h_CMD & ~wmask[29:0]) | (PWDATA[29:0] & wmask[29:0]);
      if (wr && hit[6] && !full_CMD) full_CMD <= 1'b1;
      else if (full_CMD && c_cmd_ready) full_CMD <= 1'b0;
      if (c_rsp_valid && (!avail_RSP || (rd && hit[7]))) begin
        h_RSP[0:0] <= c_rsp_ack;
        h_RSP[1:1] <= c_rsp_nak;
        h_RSP[9:2] <= c_rsp_rdata[7:0];
        avail_RSP <= 1'b1;
      end else if (rd && hit[7]) avail_RSP <= 1'b0;
      if (wr && hit[8] && !full_TX) h_TX <= (h_TX & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX[31:0] <= c_rx_data[31:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_manager = r_CFG[0:0];
  assign c_cfg_div = r_CFG[5:1];
  assign c_cfg_cols = r_CFG[7:6];
  assign c_cfg_dev = r_CFG[11:8];
  assign c_cfg_tx_col = r_CFG[15:12];
  assign c_cfg_rx_col = r_CFG[19:16];
  assign c_dev_status = r_CFG[21:20];
  assign c_cmd_op[1:0] = h_CMD[1:0];
  assign c_cmd_dev[3:0] = h_CMD[5:2];
  assign c_cmd_addr[15:0] = h_CMD[21:6];
  assign c_cmd_wdata[7:0] = h_CMD[29:22];
  assign c_tx_data[31:0] = h_TX[31:0];
  assign c_cmd_valid = full_CMD;
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_lost_sync;
    irq_set[1] = c_par_err;
    irq_set[2] = c_tx_underrun;
    irq_set[3] = full_CMD & c_cmd_ready;
    irq_set[4] = wr & (hit[6]) & full_CMD;
    irq_set[5] = c_rsp_valid & (~avail_RSP | (rd & hit[7]));
    irq_set[6] = c_rsp_valid & avail_RSP & ~(rd & hit[7]);
    irq_set[7] = full_TX & c_tx_ready;
    irq_set[8] = wr & (hit[8]) & full_TX;
    irq_set[9] = c_rx_valid & (~avail_RX | (rd & hit[9]));
    irq_set[10] = c_rx_valid & avail_RX & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_RX, full_TX, avail_RSP, full_CMD};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(h_CMD);
      10'd7: rdata = 32'(h_RSP);
      10'd8: rdata = 32'(h_TX);
      10'd9: rdata = 32'(h_RX);
      10'd10: rdata = 32'({c_ping_status, c_locked});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
